from indexing import tokens

def ranked(indexed, query, mode, labels):
    """Return a list of matching documents sorted by score and id.

    Parameters
    ----------
    indexed:
        List of ``(document, counts)`` tuples produced by :func:`indexing.index`.
    query:
        The raw query string.
    mode:
        Either ``"all"`` (every term must match) or ``"any"`` (at least one
        term must match).
    labels:
        A list of labels that every returned document must contain.
    """
    if mode not in ("all", "any"):
        raise ValueError("unknown query mode")
    # Deduplicate query terms while preserving order.
    terms = list(dict.fromkeys(tokens(query)))
    if not terms:
        return []
    result = []
    for doc, counts in indexed:
        if not all(label in doc.get("labels", []) for label in labels):
            continue
        hits = [term in counts for term in terms]
        if (mode == "all" and all(hits)) or (mode == "any" and any(hits)):
            score = sum(counts.get(term, 0) for term in terms)
            result.append({"id": doc["id"], "title": doc["title"], "score": score})
    return sorted(result, key=lambda row: (-row["score"], row["id"]))

def facets(indexed):
    """Return a mapping of label to the number of documents that contain it.

    Each document contributes at most one count per label, even if the label
    appears multiple times.
    """
    result = {}
    for doc, _ in indexed:
        for label in set(doc.get("labels", [])):
            result[label] = result.get(label, 0) + 1
    return dict(sorted(result.items()))

